vim-word-forward.solution:
def wordForward(line, col, count):
    def cls(ch):
        if ch in " \t":
            return 0
        if ch.isalnum() or ch == "_":
            return 1
        return 2
    n = len(line)
    if n == 0:
        return 0
    for _ in range(count):
        i = col
        c = cls(line[i])
        if c != 0:
            while i < n and cls(line[i]) == c:
                i += 1
        while i < n and cls(line[i]) == 0:
            i += 1
        if i >= n:
            return n - 1
        col = i
    return col

vim-word-motions.solution:
def wordMotions(line, col, keys):
    n = len(line)
    if n == 0:
        return 0

    def cls(i, big):
        ch = line[i]
        if ch in " \t":
            return 0
        if big:
            return 1
        return 1 if (ch.isalnum() or ch == "_") else 2

    for k in keys:
        big = k.isupper()
        m = k.lower()
        i = col
        if m == "w":
            t = cls(i, big)
            if t:
                while i < n and cls(i, big) == t:
                    i += 1
            while i < n and cls(i, big) == 0:
                i += 1
            col = i if i < n else n - 1
        elif m == "e":
            i += 1
            while i < n and cls(i, big) == 0:
                i += 1
            if i >= n:
                col = n - 1
            else:
                t = cls(i, big)
                while i + 1 < n and cls(i + 1, big) == t:
                    i += 1
                col = i
        else:
            i -= 1
            while i >= 0 and cls(i, big) == 0:
                i -= 1
            if i < 0:
                col = 0
            else:
                t = cls(i, big)
                while i - 1 >= 0 and cls(i - 1, big) == t:
                    i -= 1
                col = i
    return col

vim-line-anchors.solution:
def lineAnchor(line, key):
    n = len(line)
    if n == 0 or key == "0":
        return 0
    if key == "$":
        return n - 1
    if key == "^":
        for i, ch in enumerate(line):
            if ch not in " \t":
                return i
        return n - 1
    for i in range(n - 1, -1, -1):
        if line[i] not in " \t":
            return i
    return 0

vim-find-char.solution:
def findChar(line, col, keys):
    def run(kind, ch, col, repeat):
        till = kind in "tT"
        skip = 1 if (till and repeat) else 0
        if kind in "ft":
            idx = line.find(ch, col + 1 + skip)
            if idx < 0:
                return col
            return idx - 1 if till else idx
        idx = line.rfind(ch, 0, max(col - skip, 0))
        if idx < 0:
            return col
        return idx + 1 if till else idx

    flip = {"f": "F", "F": "f", "t": "T", "T": "t"}
    last = None
    i = 0
    while i < len(keys):
        k = keys[i]
        if k in "fFtT" and i + 1 < len(keys):
            last = (k, keys[i + 1])
            col = run(k, keys[i + 1], col, False)
            i += 2
            continue
        if last is not None:
            if k == ";":
                col = run(last[0], last[1], col, True)
            elif k == ",":
                col = run(flip[last[0]], last[1], col, True)
        i += 1
    return col

vim-text-object-word.solution:
def wordObject(line, col, obj):
    n = len(line)
    if n == 0:
        return [0, 0]

    def cls(i):
        ch = line[i]
        if ch in " \t":
            return 0
        return 1 if (ch.isalnum() or ch == "_") else 2

    def run(i):
        c = cls(i)
        s = i
        while s > 0 and cls(s - 1) == c:
            s -= 1
        e = i + 1
        while e < n and cls(e) == c:
            e += 1
        return s, e

    s, e = run(col)
    if obj == "iw":
        return [s, e]
    if cls(col) == 0:
        if e < n:
            _, e2 = run(e)
            return [s, e2]
        return [s, e]
    if e < n and cls(e) == 0:
        _, e2 = run(e)
        return [s, e2]
    if s > 0 and cls(s - 1) == 0:
        s2, _ = run(s - 1)
        return [s2, e]
    return [s, e]

vim-text-object-quote.solution:
def quoteObject(line, col, obj):
    kind, q = obj[0], obj[1]
    n = len(line)
    if n == 0:
        return [-1, -1]
    if line[col] == q:
        if line.count(q, 0, col + 1) % 2 == 1:
            o = col
            c = line.find(q, col + 1)
        else:
            c = col
            o = line.rfind(q, 0, col)
    else:
        o = line.rfind(q, 0, col)
        if o >= 0:
            c = line.find(q, col + 1)
        else:
            o = line.find(q, col + 1)
            c = line.find(q, o + 1) if o >= 0 else -1
    if o < 0 or c < 0:
        return [-1, -1]
    if kind == "i":
        return [o + 1, c]
    s, e = o, c + 1
    if e < n and line[e] in " \t":
        while e < n and line[e] in " \t":
            e += 1
    else:
        while s > 0 and line[s - 1] in " \t":
            s -= 1
    return [s, e]

vim-text-object-bracket.solution:
def bracketObject(line, col, obj):
    pairs = {"(": "()", ")": "()", "b": "()", "[": "[]", "]": "[]",
             "{": "{}", "}": "{}", "B": "{}"}
    op, cl = pairs[obj[1]]
    n = len(line)
    if n == 0:
        return [-1, -1]
    o = -1
    if line[col] == op:
        o = col
    else:
        depth = 0
        i = col - 1
        while i >= 0:
            if line[i] == cl:
                depth += 1
            elif line[i] == op:
                if depth == 0:
                    o = i
                    break
                depth -= 1
            i -= 1
    if o < 0:
        return [-1, -1]
    depth = 0
    c = -1
    for i in range(o + 1, n):
        if line[i] == op:
            depth += 1
        elif line[i] == cl:
            if depth == 0:
                c = i
                break
            depth -= 1
    if c < 0:
        return [-1, -1]
    return [o + 1, c] if obj[0] == "i" else [o, c + 1]

vim-text-object-tag.solution:
import re

def tagObject(line, col, obj):
    stack = []
    best = None
    for m in re.finditer(r"<(/?)([A-Za-z][A-Za-z0-9-]*)[^>]*>", line):
        if not m.group(1):
            stack.append((m.start(), m.end()))
        elif stack:
            os_, oe = stack.pop()
            cs, ce = m.start(), m.end()
            if os_ <= col < ce:
                if best is None or os_ > best[0]:
                    best = (os_, oe, cs, ce)
    if best is None:
        return [-1, -1]
    os_, oe, cs, ce = best
    return [oe, cs] if obj == "it" else [os_, ce]

vim-delete-motion.solution:
def applyDelete(line, col, cmd):
    n = len(line)
    if n == 0:
        return ["", 0]

    def cls(i):
        ch = line[i]
        if ch in " \t":
            return 0
        return 1 if (ch.isalnum() or ch == "_") else 2

    s, e = col, col
    if cmd == "x":
        e = col + 1
    elif cmd == "d$":
        e = n
    elif cmd == "d0":
        s = 0
    elif cmd == "dw":
        i = col
        t = cls(i)
        if t:
            while i < n and cls(i) == t:
                i += 1
        while i < n and cls(i) == 0:
            i += 1
        e = i
    elif cmd == "de":
        i = col + 1
        while i < n and cls(i) == 0:
            i += 1
        if i >= n:
            e = n
        else:
            t = cls(i)
            while i + 1 < n and cls(i + 1) == t:
                i += 1
            e = i + 1
    elif cmd == "db":
        i = col - 1
        while i >= 0 and cls(i) == 0:
            i -= 1
        if i < 0:
            s = 0
        else:
            t = cls(i)
            while i - 1 >= 0 and cls(i - 1) == t:
                i -= 1
            s = i
    else:
        idx = line.find(cmd[2], col + 1)
        if idx < 0:
            return [line, col]
        e = idx if cmd[1] == "t" else idx + 1
    new = line[:s] + line[e:]
    return [new, max(0, min(s, len(new) - 1))]

vim-change-command.solution:
def applyChange(line, col, cmd, text):
    n = len(line)

    def cls(i):
        ch = line[i]
        if ch in " \t":
            return 0
        return 1 if (ch.isalnum() or ch == "_") else 2

    def quote(q):
        if n == 0:
            return None
        if line[col] == q:
            if line.count(q, 0, col + 1) % 2 == 1:
                o, c = col, line.find(q, col + 1)
            else:
                o, c = line.rfind(q, 0, col), col
        else:
            o = line.rfind(q, 0, col)
            if o >= 0:
                c = line.find(q, col + 1)
            else:
                o = line.find(q, col + 1)
                c = line.find(q, o + 1) if o >= 0 else -1
        if o < 0 or c < 0:
            return None
        return o + 1, c

    def bracket(op, cl):
        if n == 0:
            return None
        o = -1
        if line[col] == op:
            o = col
        else:
            depth = 0
            for i in range(col - 1, -1, -1):
                if line[i] == cl:
                    depth += 1
                elif line[i] == op:
                    if depth == 0:
                        o = i
                        break
                    depth -= 1
        if o < 0:
            return None
        depth = 0
        for i in range(o + 1, n):
            if line[i] == op:
                depth += 1
            elif line[i] == cl:
                if depth == 0:
                    return o + 1, i
                depth -= 1
        return None

    rng = None
    if cmd == "cc":
        rng = (0, n)
    elif cmd == "C":
        rng = (col, n)
    elif cmd == "s":
        rng = (col, min(col + 1, n))
    elif cmd == "cw":
        if n == 0:
            rng = (0, 0)
        else:
            t = cls(col)
            i = col
            while i < n and cls(i) == t:
                i += 1
            rng = (col, i)
    elif cmd[:2] in ("ct", "cf"):
        idx = line.find(cmd[2], col + 1)
        if idx >= 0:
            rng = (col, idx if cmd[1] == "t" else idx + 1)
    elif cmd[:2] == "ci":
        ch = cmd[2]
        if ch in "\"'":
            rng = quote(ch)
        else:
            op, cl = {"(": "()", ")": "()", "[": "[]", "]": "[]", "{": "{}", "}": "{}"}[ch]
            rng = bracket(op, cl)
    if rng is None:
        return [line, col]
    s, e = rng
    new = line[:s] + text + line[e:]
    newcol = s + len(text) - 1 if text else s - 1
    return [new, max(newcol, 0)]

vim-normal-sim.solution:
def normalSim(lines, keys):
    buf = list(lines)
    row = col = 0
    reg = None

    def clamp(c):
        return max(0, min(c, len(buf[row]) - 1))

    def first_nonblank(s):
        for i, ch in enumerate(s):
            if ch not in " \t":
                return i
        return 0

    i = 0
    while i < len(keys):
        k = keys[i]
        line = buf[row]
        if k == "h":
            col = clamp(col - 1)
        elif k == "l":
            col = clamp(col + 1)
        elif k == "j":
            if row + 1 < len(buf):
                row += 1
                col = clamp(col)
        elif k == "k":
            if row > 0:
                row -= 1
                col = clamp(col)
        elif k == "0":
            col = 0
        elif k == "$":
            col = clamp(len(line))
        elif k == "x":
            if line:
                reg = (line[col], "c")
                buf[row] = line[:col] + line[col + 1:]
                col = clamp(col)
        elif k == "d":
            i += 1
            reg = (line, "l")
            del buf[row]
            if not buf:
                buf.append("")
            row = min(row, len(buf) - 1)
            col = first_nonblank(buf[row])
        elif k == "y":
            i += 1
            reg = (line, "l")
        elif k in "pP":
            if reg is not None:
                text, kind = reg
                if kind == "l":
                    if k == "p":
                        row += 1
                    buf.insert(row, text)
                    col = first_nonblank(text)
                else:
                    at = col + 1 if (k == "p" and line) else col
                    buf[row] = line[:at] + text + line[at:]
                    col = at + len(text) - 1
        elif k == "J":
            if row + 1 < len(buf):
                nxt = buf[row + 1].lstrip(" \t")
                sep = " "
                if line == "" or nxt == "" or line[-1] in " \t" or nxt[0] == ")":
                    sep = ""
                buf[row] = line + sep + nxt
                del buf[row + 1]
                col = clamp(len(line))
        elif k == "r":
            i += 1
            if line:
                buf[row] = line[:col] + keys[i] + line[col + 1:]
        elif k == "~":
            if line:
                buf[row] = line[:col] + line[col].swapcase() + line[col + 1:]
                col = clamp(col + 1)
        i += 1
    return [buf, row, col]

vim-registers.solution:
def registerSim(ops, queries):
    reg = {}
    for kind, name, text in ops:
        if name == "_":
            continue
        if name == "":
            if kind == "y":
                reg["0"] = text
            elif "\n" in text:
                for d in range(9, 1, -1):
                    if str(d - 1) in reg:
                        reg[str(d)] = reg[str(d - 1)]
                reg["1"] = text
            else:
                reg["-"] = text
            reg['"'] = text
        elif name.isupper():
            low = name.lower()
            reg[low] = reg.get(low, "") + text
            reg['"'] = reg[low]
        else:
            reg[name] = text
            reg['"'] = text
    return [reg.get(q, "") for q in queries]

vim-macro-expand.solution:
def expandMacro(registers, keys):
    out = []
    state = {"last": None}

    def run(s):
        i = 0
        n = len(s)
        while i < n:
            j = i
            if s[j] in "123456789":
                while j < n and s[j].isdigit():
                    j += 1
            if j + 1 < n and s[j] == "@" and (s[j + 1] == "@" or s[j + 1].islower()):
                count = int(s[i:j]) if j > i else 1
                name = s[j + 1]
                if name == "@":
                    name = state["last"]
                i = j + 2
                if name is None:
                    continue
                for _ in range(count):
                    state["last"] = name
                    run(registers.get(name, ""))
                continue
            if j > i:
                out.append(s[i:j])
                i = j
            else:
                out.append(s[i])
                i += 1

    run(keys)
    return "".join(out)

vim-ex-range.solution:
def parseRange(spec, cur, last, marks):
    def addr(s):
        i = 0
        if s[:1].isdigit():
            while i < len(s) and s[i].isdigit():
                i += 1
            base = int(s[:i])
        elif s[:1] == ".":
            base, i = cur, 1
        elif s[:1] == "$":
            base, i = last, 1
        elif s[:1] == "'":
            name = s[1:2]
            if name not in marks:
                return None
            base, i = marks[name], 2
        else:
            base = cur
        while i < len(s):
            sign = s[i]
            if sign not in "+-":
                return None
            i += 1
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            n = int(s[i:j]) if j > i else 1
            base += n if sign == "+" else -n
            i = j
        return base

    if spec == "%":
        a, b = 1, last
    else:
        parts = spec.split(",")
        if len(parts) > 2:
            return [-1, -1]
        a = addr(parts[0])
        b = addr(parts[1]) if len(parts) == 2 else a
    if a is None or b is None:
        return [-1, -1]
    if not (1 <= a <= last and 1 <= b <= last):
        return [-1, -1]
    return [min(a, b), max(a, b)]

vim-substitute.solution:
import re

def substitute(lines, start, end, pat, rep, flags):
    rx = re.compile(pat, re.I if "i" in flags else 0)

    def expand(m):
        out = []
        i = 0
        while i < len(rep):
            ch = rep[i]
            if ch == "\\" and i + 1 < len(rep):
                nx = rep[i + 1]
                if nx.isdigit():
                    g = int(nx)
                    out.append((m.group(g) or "") if g <= rx.groups else "")
                elif nx == "t":
                    out.append("\t")
                else:
                    out.append(nx)
                i += 2
            elif ch == "&":
                out.append(m.group(0))
                i += 1
            else:
                out.append(ch)
                i += 1
        return "".join(out)

    out = list(lines)
    subs = changed = 0
    limit = 0 if "g" in flags else 1
    for idx in range(start - 1, end):
        new, k = rx.subn(expand, out[idx], count=limit)
        if k:
            subs += k
            changed += 1
            if "n" not in flags:
                out[idx] = new
    return [out, subs, changed]

vim-global-command.solution:
import re

def globalCmd(lines, pat, invert, cmd):
    rx = re.compile(pat)
    hit = [(rx.search(s) is not None) != invert for s in lines]
    marked = [s for s, h in zip(lines, hit) if h]
    rest = [s for s, h in zip(lines, hit) if not h]
    if cmd == "d":
        return rest
    if cmd == "m0":
        return marked[::-1] + rest
    if cmd == "m$":
        return rest + marked
    if cmd == "t0":
        return marked[::-1] + list(lines)
    return list(lines) + marked

vim-very-magic.solution:
def veryMagicToPython(pat):
    if pat.startswith("\\v"):
        pat = pat[2:]
    classes = {"a": "[A-Za-z]", "l": "[a-z]", "u": "[A-Z]", "h": "[A-Za-z_]", "x": "[0-9A-Fa-f]"}
    special = ".^$*+?()[]{}|\\"
    out = []
    i = 0
    n = len(pat)
    while i < n:
        ch = pat[i]
        if ch == "\\" and i + 1 < n:
            nx = pat[i + 1]
            if nx in classes:
                out.append(classes[nx])
            elif nx.isalnum():
                out.append("\\" + nx)
            elif nx in special:
                out.append("\\" + nx)
            else:
                out.append(nx)
            i += 2
        elif ch in "<>":
            out.append("\\b")
            i += 1
        elif ch == "=":
            out.append("?")
            i += 1
        elif ch == "%" and i + 1 < n and pat[i + 1] == "(":
            out.append("(?:")
            i += 2
        elif ch == "{" and i + 1 < n and pat[i + 1] == "-":
            j = pat.index("}", i)
            body = pat[i + 2:j]
            out.append("{" + body + "}?" if body else "*?")
            i = j + 1
        elif ch == "[":
            j = i + 1
            if j < n and pat[j] == "^":
                j += 1
            if j < n and pat[j] == "]":
                j += 1
            while j < n and pat[j] != "]":
                j += 2 if pat[j] == "\\" else 1
            out.append(pat[i:j + 1])
            i = j + 1
        else:
            out.append(ch)
            i += 1
    return "".join(out)

vim-jump-list.solution:
def jumpList(ops):
    cur = 1
    lst = []
    idx = 0
    for op in ops:
        if op[0] == "jump":
            lst = [x for x in lst if x != cur]
            lst.append(cur)
            idx = len(lst)
            cur = op[1]
        elif op[0] == "back":
            if idx == len(lst):
                lst = [x for x in lst if x != cur]
                lst.append(cur)
                idx = len(lst) - 1
            if idx > 0:
                idx -= 1
                cur = lst[idx]
        else:
            if idx < len(lst) - 1:
                idx += 1
                cur = lst[idx]
    return [cur, lst]

