vim-buffer-list.solution:
def bufferSim(ops):
    cur = ""
    alt = ""
    lst = []
    for op in ops:
        kind = op[0]
        if kind == "e":
            name = op[1]
            if name == cur:
                continue
            if name not in lst:
                lst.append(name)
            if cur:
                alt = cur
            cur = name
        elif kind in ("bn", "bp"):
            if len(lst) > 1:
                i = lst.index(cur)
                step = 1 if kind == "bn" else -1
                alt = cur
                cur = lst[(i + step) % len(lst)]
        elif kind == "alt":
            if alt:
                cur, alt = alt, cur
        elif kind == "bd":
            if not cur:
                continue
            i = lst.index(cur)
            lst.pop(i)
            if alt:
                cur = alt
            elif lst:
                cur = lst[i] if i < len(lst) else lst[-1]
            else:
                cur = ""
            alt = ""
    return [cur, alt, lst]

vim-visual-block-insert.solution:
def blockEdit(lines, top, bottom, col, mode, text):
    out = list(lines)
    for r in range(top, bottom + 1):
        s = out[r]
        if mode == "I":
            if len(s) > col:
                out[r] = s[:col] + text + s[col:]
        elif mode == "A":
            if len(s) <= col:
                s = s + " " * (col + 1 - len(s))
            out[r] = s[:col + 1] + text + s[col + 1:]
        else:
            out[r] = s + text
    return out
